const fs = require("node:fs");
const path = require("node:path");
const packageJson = require("./package.json");

const bundlePath = path.join(__dirname, "dist", "index.js");
const header = `// autogenerated from ${packageJson.name}@${packageJson.version} with command build`;
const footer = "// end autogenerated";
const bundle = fs.readFileSync(bundlePath, "utf8").trimEnd();

fs.writeFileSync(bundlePath, `${header}\n${bundle}\n${footer}\n`);
